import React, { Component } from 'react';
import { requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Button } from 'reactstrap';
import { Loading } from '../Statuses/Statuses';
import Plot from 'react-plotly.js';
import { CButton } from '@coreui/react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { BACKEND_TYPING_SPEED_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "TypingSpeedGraph.js";

const initialState = {
	isLoaded: false,
	loadingModalVisible: false,
	loadingModalState: 0,
	failureModalVisible: false,
	sessionListData: null,
	graphType: "scatter",
	graphMode: "lines+markers",
	dataForPlot: null
};

class TypingSpeedGraph extends Component {

	constructor(props) {
		super(props);
		this.state = JSON.parse(JSON.stringify(initialState));
	}

	resetStateToDefault() {
		this.setState(JSON.parse(JSON.stringify(initialState)));
	}

	componentDidMount() {
		document.title = "Satanlabs - Typing Speed Graph";
		this.fetchSessionList();
	}

	fetchSessionList() {
		this.setState({
			isLoaded: false
		});
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/list?offset=0';
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_1", "result", result);
				if(result.code === 1001) {
					this.setState({
						sessionListData: result.data
					});
					this.plotData();
				} else {
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_1", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	plotData = () => {
		this.setState({
			isLoaded: false
		});

		setTimeout(() => {
			this.setState({
				dataForPlot: this.buildCombinedPlotData(),
				isLoaded: true
			});
		}, 200);
	}

	buildCombinedPlotData = () => {
		let x_wpm = [], y_wpm = [];
		let x_cpm = [], y_cpm = [];
		let x_accuracy = [], y_accuracy = [];

		this.state.sessionListData.forEach(data => {
			x_wpm.push(data.createdOn);
			y_wpm.push(data.wpm);
			x_cpm.push(data.createdOn);
			y_cpm.push(data.cpm);
			x_accuracy.push(data.createdOn);
			y_accuracy.push(data.accuracy);
		});

		return [
			{
				x: [...x_wpm],
				y: [...y_wpm],
				type: this.state.graphType,
				mode: this.state.graphMode,
				marker: { color: 'green' },
				name: 'WPM'
			},
			{
				x: [...x_cpm],
				y: [...y_cpm],
				type: this.state.graphType,
				mode: this.state.graphMode,
				marker: { color: 'blue' },
				name: 'CPM'
			},
			{
				x: [...x_accuracy],
				y: [...y_accuracy],
				type: this.state.graphType,
				mode: this.state.graphMode,
				marker: { color: 'orange' },
				name: 'Accuracy (%)',
				yaxis: 'y2'
			}
		];
	}

	reloadData() {
		this.resetStateToDefault();
		this.fetchSessionList();
	}

	render() {
		Logger(FILE_NAME, "render", "", "this.state", this.state);
		const width = window.innerWidth * 0.85;
		const height = window.innerHeight * 0.50;

		return (
			<div>
				<a href="#/typing-speed" style={{ textDecoration: 'none' }}>
					<CButton color="secondary" className="mb-3">← Back to Typing Sessions</CButton>
				</a>
				{
					this.state.isLoaded ?
					<div>
						<h2>Typing Speed Graphs</h2>
						<CButton color="success" className="px-4" onClick={() => this.reloadData()}>reloadData</CButton>
						<br /><br />
						<div>
							<span>
								<b>Change Type :</b>&nbsp;&nbsp;
								<Button color="primary" size="lg" onClick={() => { this.setState({ graphType: "scatter" }); this.plotData(); }}>scatter TYPE</Button>
								&nbsp;&nbsp;&nbsp;&nbsp;
								<Button color="warning" size="lg" onClick={() => { this.setState({ graphType: "bar" }); this.plotData(); }}>bar TYPE</Button>
								&nbsp;&nbsp;&nbsp;&nbsp;
								CURRENT Type : [ {this.state.graphType} ]
								<br /><br />
							</span>
							<span>
								<b>Change Mode :</b>&nbsp;&nbsp;
								<Button color="primary" size="lg" onClick={() => { this.setState({ graphMode: "lines" }); this.plotData(); }}>lines MODE</Button>
								&nbsp;&nbsp;&nbsp;&nbsp;
								<Button color="danger" size="lg" onClick={() => { this.setState({ graphMode: "lines+markers" }); this.plotData(); }}>lines+markers MODE</Button>
								&nbsp;&nbsp;&nbsp;&nbsp;
								<Button color="warning" size="lg" onClick={() => { this.setState({ graphMode: "markers" }); this.plotData(); }}>markers MODE</Button>
								&nbsp;&nbsp;&nbsp;&nbsp;
								CURRENT Mode : [ {this.state.graphMode} ]
								<br /><br />
							</span>
						</div>
						<Plot
							data={this.state.dataForPlot}
							layout={{
								width,
								height,
								title: 'Typing Speed - WPM, CPM & Accuracy',
								showlegend: true,
								legend: { orientation: 'h', y: -0.2 },
								yaxis: { title: 'WPM / CPM' },
								yaxis2: {
									title: 'Accuracy (%)',
									overlaying: 'y',
									side: 'right',
									range: [0, 100]
								}
							}}
						/>
						<StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
						<FailureModal visible={this.state.failureModalVisible} />
					</div>
					: <Loading />
				}
			</div>
		);
	}
}

export default TypingSpeedGraph;
